// Read what Lua published and summarise it.
const brackets = nb.get('bracket_results') || [];
const spool = nb.get('spool_order') || [];

console.log('bracket checks:', brackets.filter(r => r.ok).length + '/' + brackets.length, 'balanced');
console.log('print completion order:', spool.join(' -> '));

return {
  balanced: brackets.filter(r => r.ok).map(r => r.text),
  unbalanced: brackets.filter(r => !r.ok).map(r => r.text),
  completionOrder: spool,
};
